input.command:
python - <<'EOF'
import json
from catalog.service import Catalog
c = Catalog(); a=c.create("A","x"); b=c.create("B","y"); d=c.create("D","z"); c.delete(b); c.update(a, title="A2")
dump = c.export()
e = Catalog(); pre = e.create("Pre","p"); e.import_(dump)
assert [r["id"] for r in e.list()] == [pre, a, d], e.list()
assert e.get(a)["title"] == "A2"
# atomic: bad dump leaves catalog unchanged
bad = json.dumps([{"id":"new1","title":"t","author":"u"}, {"id":a,"title":"t","author":"u"}])
try: e.import_(bad); raise SystemExit("expected ValueError")
except ValueError as ex: print("rejected:", ex)
assert "new1" not in {r["id"] for r in e.list()}
for bad in ["not json", "{}", "[1]", '[{"id":"","title":"t","author":"u"}]', '[{"id":"q","title":1,"author":"u"}]']:
    try: Catalog().import_(bad); raise SystemExit(f"expected ValueError for {bad!r}")
    except ValueError as ex: print("rejected:", ex)
assert Catalog().find("x") == []
print("edge cases OK")
EOF
git status --short

